/**
 * Browser integration tests render actual Demon Hunter God and owner-view
 * fixtures across board sizes, win policies and locales. Archive/checkpoint
 * facts and literal winner assertions check choice timing, hidden identities
 * and the terminal Hunter death chain without executing a duel or rule engine.
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { eventLabel } from "../../src/replay/event-labels";
import { readReplayPlayerView } from "@ai-werewolf-arena/replay-contract";
const read = (name: string) =>
  JSON.parse(readFileSync(frontendFixtureURL(`frontend/tests/fixtures/${name}`), "utf8"));
for (const size of [6, 12])
  for (const goal of ["slaughter_city", "slaughter_side"])
    for (const locale of ["zh-CN", "en"] as const)
      test(`${size}/${goal}/${locale}: actual God choice has no premature deaths and final native winners`, async ({
        page,
      }) => {
        const key = `demon-hunter-${size}-${goal}`,
          replay = read(`${key}.replay.json`),
          cp = read(`checkpoints/${key}.json`);
        replay.meta.locale = locale;
        const chosen = replay.events.find((e: any) => e.type === "demon_hunter_chosen"),
          label = eventLabel(chosen, locale);
        await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
        await page.goto("/");
        await page.locator(".timeline .event").filter({ hasText: label }).click();
        await expect(page.getByTestId("composition-event")).toHaveText(label);
        await expect(page.locator(".seat-grid .dead")).toHaveCount(0);
        await expect(
          page.locator(`[data-composition-player="${chosen.payload.actorId}"]`),
        ).toContainText(locale === "en" ? "Demon Hunter" : "猎魔人");
        await page.locator(".timeline .event").last().click();
        await expect(page.locator(".seat-grid .dead")).toHaveCount(
          cp.players.filter((p: any) => !p.alive).length,
        );
        await expect(page.getByTestId("composition-winner")).toHaveCount(size === 6 ? 4 : 9);
        if (size === 12 && goal === "slaughter_city")
          await page.screenshot({
            path: `/tmp/awa-p9-demon-${locale}-browser.png`,
            fullPage: true,
          });
      });
for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: actual owner lean choice reveals no other role and no God toxin outcome`, async ({
    page,
  }) => {
    const god = read("demon-hunter-12-slaughter_city.replay.json"),
      view = readReplayPlayerView(read("player-views/demon-hunter-12-slaughter_city.player.json"));
    const own = view.timeline.find(
      (r) => r.kind === "event" && r.event.type === "demon_hunter_chosen",
    );
    if (!own || own.kind !== "event") throw new Error("missing_owner_choice");
    const event = {
      seq: 2,
      timestamp: own.timestamp!,
      phase: own.phase,
      day: own.day,
      type: own.event.type,
      payload: own.event.payload,
    };
    expect(event.payload).not.toHaveProperty("actorId");
    const replay = {
      ...god,
      meta: { ...god.meta, locale },
      players: god.players.map((p: any) => ({
        ...p,
        role: p.player_id === view.player_id ? view.role : "unknown",
        camp: p.player_id === view.player_id ? view.camp : "unknown",
      })),
      events: [
        {
          seq: 1,
          timestamp: event.timestamp,
          phase: "night",
          day: 2,
          type: "phase_changed",
          payload: { phase: "night", day: 2 },
        },
        event,
      ],
    };
    await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
    await page.goto("/");
    const label = eventLabel(event, locale);
    await page.locator(".timeline .event").filter({ hasText: label }).click();
    await expect(page.getByTestId("composition-event")).toHaveText(label);
    for (const p of replay.players.filter((p: any) => p.player_id !== view.player_id))
      await expect(page.locator(`[data-composition-player="${p.player_id}"]`)).toContainText(
        "unknown",
      );
    await expect(page.locator(".seat-grid .dead")).toHaveCount(0);
  });
for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: terminal Night includes Hunter extra death and dead Good winners before Day`, async ({
    page,
  }) => {
    const replay = read("demon-hunter-terminal.replay.json"),
      cp = read("checkpoints/demon-hunter-terminal.json");
    replay.meta.locale = locale;
    await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
    await page.goto("/");
    await page.locator(".timeline .event").last().click();
    await expect(page.locator(".seat-grid .dead")).toHaveCount(4);
    await expect(page.getByTestId("composition-winner")).toHaveCount(9);
    const deadIds = await page.locator(".seat-grid .dead .seat-number").allTextContents();
    expect(deadIds.map(Number)).toEqual(
      cp.players.filter((p: any) => !p.alive).map((p: any) => p.id),
    );
  });

/**
 * Browser integration tests render recorded Evil Knight inspection and gun
 * policy fixtures in both locales. Assertions seek the recorded inspection,
 * shot and terminal frames to check labels, living seats and winner timing;
 * these tests consume settled archives without executing a game.
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "../../src/replay/event-labels";
for (const kind of ["night_immune_wolf", "shot_bypass_good", "day_shot_good"] as const)
  for (const locale of ["zh-CN", "en"] as const)
    test(`evil knight ${kind}/${locale}: inspection does not pre-kill and gun policy reaches exact terminal board`, async ({
      page,
    }) => {
      const replay = readReplayDocument(
        JSON.parse(
          readFileSync(
            frontendFixtureURL(`frontend/tests/fixtures/evil-knight-${kind}-${locale}.replay.json`),
            "utf8",
          ),
        ),
      );
      const report = replay.events.find((e) => e.type === "seer_checked")!;
      const label = eventLabel(report, locale);
      await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
      await page.goto("/");
      await page.locator(".timeline .event").filter({ hasText: label }).first().click();
      await expect(page.getByTestId("composition-event")).toHaveText(label);
      await expect(page.locator(".seat-grid .dead")).toHaveCount(0);
      await expect(page.getByTestId("composition-winner")).toHaveCount(0);
      await expect(page.locator("[data-composition-player]")).toHaveCount(12);
      await page.locator(".timeline .event").last().click();
      await expect(page.locator(".seat-grid .dead")).toHaveCount(
        kind === "night_immune_wolf" ? 4 : 6,
      );
      await expect(page.getByTestId("composition-winner")).toHaveCount(
        kind === "night_immune_wolf" ? 4 : 8,
      );
    });

/**
 * Browser integration tests render recorded Magician fixtures for original
 * and exchanged gun targets in both locales. The archive event order supplies
 * the assertions for unchanged seats, night-miss captions and terminal winners;
 * the browser exercises replay frames rather than resolving game actions.
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "../../src/replay/event-labels";
for (const policy of ["original", "exchanged"] as const)
  for (const locale of ["zh-CN", "en"] as const)
    test(`Magician exchange preserves seats and night miss causes no extra death/${policy}/${locale}`, async ({
      page,
    }) => {
      const base = "frontend/tests/fixtures/magician-" + policy + "-" + locale;
      const replay = readReplayDocument(
        JSON.parse(readFileSync(frontendFixtureURL(base + ".replay.json"), "utf8")),
      );
      const cp = JSON.parse(
        readFileSync(frontendFixtureURL(base + ".checkpoint.txt"), "utf8"),
      ) as { players: Array<{ id: number; role: string; alive: boolean }> };
      await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
      await page.goto("/");
      const exchange = replay.events.find((e) => e.type === "magician_exchange_committed")!;
      const label = eventLabel(exchange, locale);
      await page.locator(".timeline .event").filter({ hasText: label }).first().click();
      await expect(page.getByTestId("composition-event")).toHaveText(label);
      await expect(page.locator(".seat-grid .dead")).toHaveCount(0);
      await expect(page.locator("[data-composition-player]")).toHaveCount(12);
      await expect(page.getByTestId("composition-winner")).toHaveCount(0);
      if (policy === "exchanged") {
        const miss = replay.events.find((e) => e.type === "death_shot_missed")!;
        const missLabel = eventLabel(miss, locale);
        await page.locator(".timeline .event").filter({ hasText: missLabel }).first().click();
        await expect(page.getByTestId("composition-event")).toHaveText(missLabel);
        await expect(page.locator(".seat-grid .dead")).toHaveCount(2);
      }
      await page.locator(".timeline .event").last().click();
      const dead = await page.locator(".seat-grid .dead .seat-number").allTextContents();
      expect(dead.map(Number)).toEqual(cp.players.filter((p) => !p.alive).map((p) => p.id));
      await expect(page.getByTestId("composition-winner")).not.toHaveCount(0);
    });

/**
 * Browser integration tests seek and rewind a recorded Mist Raven badge chain
 * in both locales. Literal expected badge holders and archived event captions
 * check each handoff frame and the absence of premature winners; no badge
 * transfer or game rule is performed by this test.
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "../../src/replay/event-labels";
for (const locale of ["en", "zh-CN"] as const)
  test(`Mist literal badge 10 to pending 5 to 6 and reverse/${locale}`, async ({ page }) => {
    const r = readReplayDocument(
      JSON.parse(
        readFileSync(
          frontendFixtureURL(`frontend/tests/fixtures/mist-manual-blast-badge-chain-${locale}.replay.json`),
          "utf8",
        ),
      ),
    );
    await page.route("**/api/replay", (route) => route.fulfill({ json: r }));
    await page.goto("/");
    const blast = r.events.find((e) => e.type === "wolf_self_destruct")!;
    const first = r.events.find(
      (e) => e.type === "sheriff_badge_transferred" && e.payload.fromId === 10,
    )!;
    const snake = r.events.find((e) => e.type === "alchemist_snake_chosen" && e.day === 1)!;
    const night = r.events.find((e) => e.type === "night_resolved" && e.day === 1)!;
    const second = r.events.find(
      (e) => e.type === "sheriff_badge_transferred" && e.payload.fromId === 5,
    )!;
    for (const [e, holder, living] of [
      [blast, 10, false],
      [first, 5, true],
      [snake, 5, true],
      [night, 5, false],
      [second, 6, true],
      [night, 5, false],
      [snake, 5, true],
      [blast, 10, false],
    ] as const) {
      const label = eventLabel(e, locale);
      await page.locator(".timeline .event").filter({ hasText: label }).first().click();
      await expect(page.getByTestId("composition-event")).toHaveText(label);
      expect(
        (
          await page
            .locator(".seat-grid .seat")
            .filter({ has: page.locator(".sheriff") })
            .locator(".seat-number")
            .allTextContents()
        ).map(Number),
      ).toEqual([holder]);
      await expect(page.locator(`[data-composition-player="${holder}"]`)).toContainText(
        locale === "en" ? "Sheriff" : "警长",
      );
      await expect(page.locator(`[data-composition-player="${holder}"]`)).toHaveCSS(
        "opacity",
        living ? "1" : "0.35",
      );
      await expect(page.getByTestId("composition-winner")).toHaveCount(0);
    }
  });

/**
 * Browser integration tests build minimal render inputs from actual Mist
 * Raven alchemist, raven and villager player-view fixtures. Assertions seek
 * and rewind the owner-visible events in both locales, checking private labels,
 * hidden identities and winner timing without adding God-view information.
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument, readReplayPlayerView } from "@ai-werewolf-arena/replay-contract";
import { createReplayRenderInput } from "../../src/replay/replay-frame";
import { eventLabel } from "../../src/replay/event-labels";
import { roleName } from "../../src/replay/replay-localization";
for (const actor of ["alchemist", "raven", "villager"] as const)
  for (const locale of ["en", "zh-CN"] as const)
    test(`Mist actual owner minimal movie input and rewind/${actor}/${locale}`, async ({
      page,
    }) => {
      const name = `mist-normal-linked-${locale}`;
      const god = readReplayDocument(
        JSON.parse(
          readFileSync(frontendFixtureURL(`frontend/tests/fixtures/${name}.replay.json`), "utf8"),
        ),
      );
      const view = readReplayPlayerView(
        JSON.parse(
          readFileSync(
            frontendFixtureURL(`frontend/tests/fixtures/player-views/${name}-${actor}.player.json`),
            "utf8",
          ),
        ),
      );
      const events = view.timeline.flatMap((row) =>
        row.kind === "event"
          ? [
              {
                seq: row.seq,
                timestamp: row.timestamp!,
                day: row.day,
                phase: row.phase,
                type: row.event.type,
                payload: row.event.payload,
              },
            ]
          : [],
      );
      // Minimal render contract using actual authorized archive, not a private-file UI import.
      const replay = readReplayDocument({
        ...god,
        result: { winner: null, reason: "private_render" },
        players: god.players.map((p) => ({
          ...p,
          role: p.player_id === view.player_id ? view.role : "unknown",
          camp: p.player_id === view.player_id ? view.camp : "unknown",
        })),
        events: events.map((e, i) => ({ ...e, seq: i + 1 })),
      });
      await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
      await page.goto("/");
      const input = createReplayRenderInput(replay, { locale, timeZone: "UTC" });
      const type =
        actor === "alchemist"
          ? "alchemist_snake_chosen"
          : actor === "raven"
            ? "raven_unsealed"
            : "night_resolved";
      const event = replay.events.find((e) => e.type === type && e.day === 2)!;
      const label = eventLabel(event, locale);
      await page.locator(".timeline .event").filter({ hasText: label }).first().click();
      await expect(page.getByTestId("composition-event")).toHaveText(label);
      for (const p of replay.players) {
        await expect(page.locator(`[data-composition-player="${p.player_id}"]`)).toContainText(
          roleName(p.player_id === view.player_id ? view.role : "unknown", locale),
        );
      }
      if (actor !== "alchemist")
        expect(replay.events.some((e) => e.type.startsWith("alchemist_"))).toBe(false);
      if (actor !== "raven")
        expect(replay.events.some((e) => e.type.startsWith("raven_"))).toBe(false);
      const index = input.replay.events.findIndex((e) => e.seq === event.seq);
      const slider = page.locator('.frame-control input[type="range"]');
      for (const frame of [index * 90 + 45, index * 90 - 1, 0]) {
        await slider.evaluate((el, value) => {
          Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")!.set!.call(
            el,
            String(value),
          );
          el.dispatchEvent(new Event("input", { bubbles: true }));
          el.dispatchEvent(new Event("change", { bubbles: true }));
        }, frame);
        await expect(slider).toHaveValue(String(frame));
        await expect(page.getByTestId("composition-event")).toHaveAttribute(
          "data-event-seq",
          String(input.replay.events[Math.floor(frame / 90)]!.seq),
        );
        await expect(page.getByTestId("composition-winner")).toHaveCount(0);
      }
      expect(await page.locator(".seat-grid .dead .seat-number").allTextContents()).toEqual([]);
    });

/**
 * Browser integration tests seek and rewind actual Mist Raven replay fixtures
 * for linked deaths, saved/protected targets and manual outcomes in both
 * locales. Archived events and literal frame assertions check night disclosure,
 * seat changes and winner timing without replaying the game mechanics.
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "../../src/replay/event-labels";
import { createReplayRenderInput } from "../../src/replay/replay-frame";
const cases = [
  "normal-linked",
  "normal-saved-dreamer",
  "normal-protected-heal",
  "normal-draw",
  "manual-blast-pre-election",
  "manual-blast-daybreak",
  "manual-blast-speech-gap",
  "manual-blast-pre-vote",
  "manual-blast-raw-target",
  "manual-blast-badge-chain",
  "manual-blast-last-wolf",
  "manual-blast-parallel-raw-loser",
  "manual-blast-parallel-second-gap",
];
for (const variant of cases)
  for (const locale of ["en", "zh-CN"] as const)
    test(`Mist actual replay frame, night disclosure and rewind/${variant}/${locale}`, async ({
      page,
    }) => {
      const name = `mist-${variant}-${locale}`;
      const replay = readReplayDocument(
        JSON.parse(
          readFileSync(frontendFixtureURL(`frontend/tests/fixtures/${name}.replay.json`), "utf8"),
        ),
      );
      const cp = JSON.parse(
        readFileSync(frontendFixtureURL(`frontend/tests/fixtures/${name}.checkpoint.txt`), "utf8"),
      ) as { players: Array<{ id: number; alive: boolean }> };
      await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
      await page.goto("/");
      const dead = async () =>
        (await page.locator(".seat-grid .dead .seat-number").allTextContents()).map(Number);
      const expected = (index: number) => {
        const deaths = new Set<number>();
        for (const e of replay.events.slice(0, index + 1)) {
          if (e.type === "night_resolved")
            for (const id of e.payload.deaths as number[]) deaths.add(id);
          if (e.type === "wolf_self_destruct") deaths.add(Number(e.payload.wolfId));
          if (e.type === "voted_out") deaths.add(Number(e.payload.target));
        }
        return [...deaths].sort((a, b) => a - b);
      };
      const input = createReplayRenderInput(replay, { locale, timeZone: "UTC" });
      const seek = async (frame: number) => {
        const slider = page.locator('.frame-control input[type="range"]');
        await slider.evaluate((el, value) => {
          Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")!.set!.call(
            el,
            String(value),
          );
          el.dispatchEvent(new Event("input", { bubbles: true }));
          el.dispatchEvent(new Event("change", { bubbles: true }));
        }, frame);
        await expect(slider).toHaveValue(String(frame));
      };
      const compositionDead = async () =>
        page
          .locator("[data-composition-player]")
          .evaluateAll((nodes) =>
            nodes
              .filter((n) => Number((n as HTMLElement).style.opacity) < 1)
              .map((n) => Number(n.getAttribute("data-composition-player"))),
          );
      const critical = replay.events.filter((e) =>
        [
          "alchemist_snake_chosen",
          "raven_knife_chosen",
          "mist_knife_drawn",
          "wolf_self_destruct",
          "night_resolved",
          "sheriff_badge_transferred",
          "game_over",
        ].includes(e.type),
      );
      for (const e of critical) {
        const label = eventLabel(e, locale);
        await page.locator(".timeline .event").filter({ hasText: label }).first().click();
        await expect(page.getByTestId("composition-event")).toHaveText(label);
        expect(await dead()).toEqual(expected(replay.events.findIndex((x) => x.seq === e.seq)));
        expect(await compositionDead()).toEqual(
          expected(replay.events.findIndex((x) => x.seq === e.seq)),
        );
        const frameIndex = input.replay.events.findIndex((x) => x.seq === e.seq);
        await seek(frameIndex * 90 + 45);
        await expect(page.getByTestId("composition-event")).toHaveText(label);
        expect(await compositionDead()).toEqual(
          expected(replay.events.findIndex((x) => x.seq === e.seq)),
        );
        if (frameIndex > 0) {
          await seek(frameIndex * 90 - 1);
          await expect(page.getByTestId("composition-event")).toHaveAttribute(
            "data-event-seq",
            String(input.replay.events[frameIndex - 1]!.seq),
          );
          const previous = expected(
            replay.events.findIndex((x) => x.seq === input.replay.events[frameIndex - 1]!.seq),
          );
          expect(await dead()).toEqual(previous);
          expect(await compositionDead()).toEqual(previous);
          await seek(frameIndex * 90 + 45);
        }
        if (e.type === "sheriff_badge_transferred") {
          const holder = Number(e.payload.toId);
          expect(
            (
              await page
                .locator(".seat-grid .seat")
                .filter({ has: page.locator(".sheriff") })
                .locator(".seat-number")
                .allTextContents()
            ).map(Number),
          ).toEqual([holder]);
          await expect(page.locator(`[data-composition-player="${holder}"]`)).toContainText(
            locale === "en" ? "Sheriff" : "警长",
          );
        }
        if (e.type !== "game_over")
          await expect(page.getByTestId("composition-winner")).toHaveCount(0);
      }
      const final = cp.players.filter((p) => !p.alive).map((p) => p.id);
      await page.locator(".timeline .event").last().click();
      expect(await dead()).toEqual(final);
      await expect(page.getByTestId("composition-winner")).not.toHaveCount(0);
      await page.locator(".timeline .event").first().click();
      expect(await dead()).toEqual([]);
      await expect(page.getByTestId("composition-winner")).toHaveCount(0);
      const other = locale === "en" ? "zh-CN" : "en";
      await page.locator(".display-controls select").nth(0).selectOption(other);
      await page.locator(".display-controls select").nth(1).selectOption("UTC");
      expect(await dead()).toEqual([]);
      await page.locator(".timeline .event").last().click();
      expect(await dead()).toEqual(final);
      await page.reload();
      await page.locator(".timeline .event").last().click();
      expect(await dead()).toEqual(final);
    });

/**
 * Browser integration tests render a recorded Nightmare fear and Hunter-shot
 * fixture in both locales. Archived events and literal seat/winner assertions
 * check that fear does not kill a seat and the terminal shot remains visible;
 * the tests only play and seek the recorded replay.
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "../../src/replay/event-labels";
for (const locale of ["zh-CN", "en"] as const)
  test(`nightmare fear is not a death and terminal Hunter shot remains visible/${locale}`, async ({
    page,
  }) => {
    const replay = readReplayDocument(
      JSON.parse(
        readFileSync(
          frontendFixtureURL(`frontend/tests/fixtures/nightmare-${locale}.replay.json`),
          "utf8",
        ),
      ),
    );
    const fear = replay.events.find((e) => e.type === "nightmare_fear_committed")!;
    const label = eventLabel(fear, locale);
    await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
    await page.goto("/");
    await page.locator(".timeline .event").filter({ hasText: label }).first().click();
    await expect(page.getByTestId("composition-event")).toHaveText(label);
    await expect(page.locator(".seat-grid .dead")).toHaveCount(0);
    await expect(page.getByTestId("composition-winner")).toHaveCount(0);
    await expect(page.locator("[data-composition-player]")).toHaveCount(12);
